import sqlite3

# Flat file style: the city is repeated on every line
flat = [("Asha", "Pune", 5), ("Asha", "Pune", 7), ("Asha", "Pune", 2)]
flat[1] = ("Asha", "Pnue", 7)  # one typo creates an inconsistency
print("flat file cities for Asha:", sorted({r[1] for r in flat}))

db = sqlite3.connect(":memory:")
db.executescript("""
CREATE TABLE customers(id INTEGER PRIMARY KEY, name TEXT, city TEXT);
CREATE TABLE orders(id INTEGER PRIMARY KEY, cust_id INTEGER REFERENCES customers(id),
                    qty INTEGER CHECK(qty > 0));
INSERT INTO customers VALUES (1,'Asha','Pune');
INSERT INTO orders(cust_id,qty) VALUES (1,5),(1,7),(1,2);
""")
# the city is stored once, so one UPDATE fixes every order
db.execute("UPDATE customers SET city='Mumbai' WHERE id=1")
print("DBMS join after one update:")
for r in db.execute("SELECT o.id, c.name, c.city, o.qty FROM orders o JOIN customers c ON c.id=o.cust_id"):
    print(" ", r)
# a constraint rejects bad data that a spreadsheet would accept
try:
    db.execute("INSERT INTO orders(cust_id,qty) VALUES (1,-3)")
except sqlite3.IntegrityError as e:
    print("rejected:", e)

import sqlite3

db = sqlite3.connect(":memory:")
db.execute("PRAGMA foreign_keys = ON")
db.executescript("""
CREATE TABLE users(id INTEGER PRIMARY KEY, email TEXT NOT NULL UNIQUE);
CREATE TABLE posts(id INTEGER PRIMARY KEY, user_id INT REFERENCES users(id), title TEXT);
INSERT INTO users(email) VALUES ('old@mail.com');
INSERT INTO posts(user_id,title) VALUES (1,'hello'),(1,'again');
""")
# natural key would have to change in every child row; surrogate id changes nowhere
db.execute("UPDATE users SET email='new@mail.com' WHERE id=1")
print("posts still linked:", db.execute(
    "SELECT p.title, u.email FROM posts p JOIN users u ON u.id=p.user_id").fetchall())
# the UNIQUE on the natural key still blocks duplicate real people
try:
    db.execute("INSERT INTO users(email) VALUES ('new@mail.com')")
except sqlite3.IntegrityError as e:
    print("duplicate email rejected:", e)

import sqlite3

db = sqlite3.connect(":memory:")
db.execute("PRAGMA foreign_keys = ON")  # SQLite needs this per connection
db.executescript("""
CREATE TABLE dept(id INTEGER PRIMARY KEY, name TEXT);
CREATE TABLE emp(id INTEGER PRIMARY KEY, name TEXT,
                 dept_id INT REFERENCES dept(id) ON DELETE RESTRICT);
INSERT INTO dept VALUES (1,'Sales');
INSERT INTO emp VALUES (1,'Ann',1);
""")
def attempt(label, sql):
    try:
        db.execute(sql)
        print(label, "-> ok")
    except sqlite3.IntegrityError as e:
        print(label, "-> rejected:", e)

attempt("child with missing parent", "INSERT INTO emp VALUES (2,'Bob',99)")  # orphan
attempt("child with NULL fk", "INSERT INTO emp VALUES (3,'Cy',NULL)")       # allowed
attempt("delete parent with children", "DELETE FROM dept WHERE id=1")       # RESTRICT
print("emp rows:", db.execute("SELECT * FROM emp").fetchall())

import sqlite3

db = sqlite3.connect(":memory:")
db.execute("PRAGMA foreign_keys = ON")
db.executescript("""
CREATE TABLE orders(id INTEGER PRIMARY KEY);
CREATE TABLE order_items(id INTEGER PRIMARY KEY,
    order_id INT REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE customers(id INTEGER PRIMARY KEY);
CREATE TABLE invoices(id INTEGER PRIMARY KEY,
    cust_id INT REFERENCES customers(id) ON DELETE CASCADE);
CREATE TABLE safe_invoices(id INTEGER PRIMARY KEY,
    cust_id INT REFERENCES customers(id) ON DELETE RESTRICT);
INSERT INTO orders VALUES (1);
INSERT INTO order_items(order_id) VALUES (1),(1),(1);
INSERT INTO customers VALUES (7);
INSERT INTO invoices(cust_id) VALUES (7),(7);
""")
count = lambda t: db.execute(f"SELECT COUNT(*) FROM {t}").fetchone()[0]
db.execute("DELETE FROM orders WHERE id=1")
print("items after deleting order (good cascade):", count("order_items"))
db.execute("INSERT INTO safe_invoices(cust_id) VALUES (7)")
try:
    db.execute("DELETE FROM customers WHERE id=7")
except sqlite3.IntegrityError as e:
    print("RESTRICT protects history:", e)
db.execute("DELETE FROM safe_invoices")
db.execute("DELETE FROM customers WHERE id=7")  # cascade now wipes invoices
print("invoices after deleting customer (dangerous cascade):", count("invoices"))

import sqlite3

db = sqlite3.connect(":memory:")
db.execute("PRAGMA foreign_keys = ON")
db.executescript("""
CREATE TABLE departments(id INTEGER PRIMARY KEY, name TEXT);
CREATE TABLE students(id INTEGER PRIMARY KEY, name TEXT,
    dept_id INT REFERENCES departments(id));              -- 1:N, FK on the many side
CREATE TABLE id_cards(id INTEGER PRIMARY KEY,
    student_id INT UNIQUE REFERENCES students(id));       -- 1:1, FK + UNIQUE
CREATE TABLE courses(id INTEGER PRIMARY KEY, title TEXT);
CREATE TABLE enrollments(student_id INT REFERENCES students(id),
    course_id INT REFERENCES courses(id), grade TEXT,
    PRIMARY KEY(student_id, course_id));                  -- N:M junction
INSERT INTO departments VALUES (1,'CS');
INSERT INTO students VALUES (1,'Ann',1),(2,'Raj',1);
INSERT INTO id_cards(student_id) VALUES (1);
INSERT INTO courses VALUES (10,'DB'),(11,'OS');
INSERT INTO enrollments VALUES (1,10,'A'),(1,11,'B'),(2,10,'C');
""")
