    db.execute("INSERT INTO id_cards(student_id) VALUES (1)")
except sqlite3.IntegrityError as e:
    print("second card for same student rejected:", e)
print("students per dept:", db.execute("SELECT d.name, COUNT(*) FROM students s JOIN departments d ON d.id=s.dept_id GROUP BY d.name").fetchall())
for r in db.execute("""SELECT s.name, c.title, e.grade FROM enrollments e
    JOIN students s ON s.id=e.student_id JOIN courses c ON c.id=e.course_id ORDER BY 1,2"""):
    print(r)

import sqlite3

db = sqlite3.connect(":memory:")
db.executescript("""
CREATE TABLE enrollments(student_id INT, course_id INT, grade TEXT,
    PRIMARY KEY(student_id, course_id));
CREATE INDEX idx_course ON enrollments(course_id);  -- second direction: course -> students
INSERT INTO enrollments VALUES (1,10,'F'),(2,10,'A');
""")
try:
    db.execute("INSERT INTO enrollments VALUES (1,10,'B')")  # student 1 retakes course 10
except sqlite3.IntegrityError as e:
    print("retake rejected with pair key:", e)
# the junction is its own entity: add the semester to the key
db.executescript("""
CREATE TABLE enrol2(student_id INT, course_id INT, semester TEXT, grade TEXT,
    PRIMARY KEY(student_id, course_id, semester));
INSERT INTO enrol2 VALUES (1,10,'2025F','F');
INSERT INTO enrol2 VALUES (1,10,'2026S','B');
""")
print("student 1 history:", db.execute("SELECT * FROM enrol2 WHERE student_id=1").fetchall())
print("one course -> many rows:", db.execute("SELECT COUNT(*) FROM enrollments WHERE course_id=10").fetchone()[0])

import sqlite3

