    user_id INT NOT NULL REFERENCES users ON DELETE CASCADE, url TEXT);
CREATE TABLE tags(tag_id INTEGER PRIMARY KEY, name TEXT UNIQUE);
CREATE TABLE photo_tags(photo_id INT REFERENCES photos ON DELETE CASCADE,
    tag_id INT REFERENCES tags, PRIMARY KEY(photo_id, tag_id));
CREATE TABLE follows(follower_id INT REFERENCES users, followee_id INT REFERENCES users,
    PRIMARY KEY(follower_id, followee_id), CHECK(follower_id <> followee_id));
CREATE INDEX idx_followee ON follows(followee_id, follower_id);  -- "who follows me"
