    JOIN photo_tags pt USING(photo_id) JOIN tags t USING(tag_id) GROUP BY p.photo_id""").fetchall())
print("followers per user:", db.execute(
    "SELECT followee_id, COUNT(*) FROM follows GROUP BY followee_id").fetchall())
